import "server-only";

import { query } from "./db";
import { resolveTarget } from "./entityMatch";

// A from-scratch, read-only TypeScript port of src/bulk_stats.py's
// canonical-deal headline stats. The pipeline already writes these to
// data/output/stats/headline_stats.json "for the website (or any other
// consumer) to read" (see src/write_headline_stats.py's own docstring),
// but that file lives outside this worktree (data/output/* is
// gitignored, generated by whichever pipeline run last touched it) and
// carries only summary statistics, not the per-deal values a histogram
// needs to bucket -- so instead of depending on a file this deployment
// may not have, this recomputes the same numbers from the same tables
// with the same rules and verifies against it.
//
// Verified exact parity against a real headline_stats.json snapshot:
// n_canonical_deals 964, pct_increase_cash_deals n=353 (min/median/max
// all exact), bidders_who_submitted_a_proposal median=2 max=43,
// proposals_per_deal median=7, days_first_contact_to_signing n=948
// median=290.5 (exclusion counts matched exactly: 2 no-start, 13
// no-signing, 1 negative-duration). If entity_match.py's matching rules
// or bulk_stats.py's thresholds change, re-verify against a fresh file.
//
// Deliberately NOT the "latest run only" convention the rest of this
// app uses (getLatestFactsRunForDeal) -- bulk_stats.py's own
// _fetch_canonical_deals joins every extraction_runs row for a
// canonical deal with no run filter at all, so matching its numbers
// means matching that too.
const MIN_FIRST_PRICE_USD = 0.1;
const MIN_FIRST_PRICE_PCT_OF_FINAL = 0.05;
const MAX_ABS_PCT_CHANGE = 300;

function median(values: number[]): number | null {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid];
}

interface ProposalRow {
  deal_id: string;
  target: string;
  proposer: string | null;
  date_resolved: string | null;
  price_low: number | null;
  price_high: number | null;
  consideration_type: string | null;
  status: string;
}

interface EventRow {
  deal_id: string;
  date_start: string | null;
  event_type: string;
}

function price(p: { price_low: number | null; price_high: number | null }): number | null {
  return p.price_high ?? p.price_low;
}

export interface CanonicalStats {
  nCanonicalDeals: number;
  medianBidders: { value: number; n: number } | null;
  medianProposals: { value: number; n: number } | null;
  medianDaysToSigning: { value: number; n: number } | null;
  medianPctIncreaseCash: { value: number; n: number } | null;
  pctIncreaseCashValues: number[];
}

export async function computeCanonicalStats(): Promise<CanonicalStats> {
  const [canonicalDeals, proposalRows, eventRows] = await Promise.all([
    query<{ id: string }>(`SELECT id FROM deals WHERE is_canonical`),
    query<ProposalRow>(`
      SELECT d.id AS deal_id, d.target, p.proposer, p.date_resolved, p.price_low, p.price_high,
             p.consideration_type, p.status
      FROM deals d
      JOIN extraction_runs r ON r.deal_id = d.id
      JOIN proposals p ON p.run_id = r.id
      WHERE d.is_canonical AND p.passed
    `),
    query<EventRow>(`
      SELECT d.id AS deal_id, e.date_start, e.event_type
      FROM deals d
      JOIN extraction_runs r ON r.deal_id = d.id
      JOIN events e ON e.run_id = r.id
      WHERE d.is_canonical AND e.passed AND e.date_start IS NOT NULL
    `),
  ]);

  const proposalsByDeal = new Map<string, ProposalRow[]>();
  for (const row of proposalRows) {
    const list = proposalsByDeal.get(row.deal_id) ?? [];
    list.push(row);
    proposalsByDeal.set(row.deal_id, list);
  }
  const eventsByDeal = new Map<string, EventRow[]>();
  for (const row of eventRows) {
    const list = eventsByDeal.get(row.deal_id) ?? [];
    list.push(row);
    eventsByDeal.set(row.deal_id, list);
  }

  const bidderCounts: number[] = [];
  const proposalCounts: number[] = [];
  const pctIncreaseValues: number[] = [];
  const daysToSigning: number[] = [];

  for (const deal of canonicalDeals) {
    const proposals = proposalsByDeal.get(deal.id) ?? [];
    const events = eventsByDeal.get(deal.id) ?? [];

    // bidders_who_submitted_a_proposal
    const bidders = new Set<string>();
    for (const p of proposals) {
      if (!p.proposer) continue;
      const resolved = resolveTarget(p.proposer, p.target);
      if (resolved && resolved !== p.target) bidders.add(resolved);
    }
    bidderCounts.push(bidders.size);

    // proposals_per_deal
    proposalCounts.push(proposals.length);

    // pct_increase_cash_deals
    const dated = proposals
      .filter((p): p is ProposalRow & { date_resolved: string } => p.date_resolved !== null)
      .sort((a, b) => (a.date_resolved < b.date_resolved ? -1 : a.date_resolved > b.date_resolved ? 1 : 0));
    if (dated.length >= 2) {
      const accepted = dated.filter((p) => p.status === "accepted");
      const final = accepted.length > 0 ? accepted[accepted.length - 1] : dated[dated.length - 1];
      if (final && final.consideration_type === "cash") {
        const first = dated[0];
        const firstPrice = price(first);
        const finalPrice = price(final);
        if (
          firstPrice !== null &&
          finalPrice !== null &&
          finalPrice > 0 &&
          firstPrice !== 0 &&
          firstPrice >= MIN_FIRST_PRICE_USD &&
          firstPrice >= MIN_FIRST_PRICE_PCT_OF_FINAL * Math.abs(finalPrice)
        ) {
          const pct = ((finalPrice - firstPrice) / firstPrice) * 100;
          if (Math.abs(pct) <= MAX_ABS_PCT_CHANGE) pctIncreaseValues.push(pct);
        }
      }
    }

    // days_first_contact_to_signing
    const firstContacts = events
      .filter((e) => e.event_type === "first_contact")
      .map((e) => e.date_start!)
      .sort();
    let processStart: string | null = firstContacts[0] ?? null;
    if (!processStart) {
      const allDates = [
        ...events.map((e) => e.date_start!),
        ...proposals.filter((p) => p.date_resolved !== null).map((p) => p.date_resolved!),
      ].sort();
      processStart = allDates[0] ?? null;
    }
    if (processStart) {
      const signings = events
        .filter((e) => e.event_type === "signing")
        .map((e) => e.date_start!)
        .sort();
      const signingDate = signings[signings.length - 1] ?? null;
      if (signingDate) {
        const days = Math.round(
          (new Date(signingDate).getTime() - new Date(processStart).getTime()) / (1000 * 60 * 60 * 24)
        );
        if (days >= 0) daysToSigning.push(days);
      }
    }
  }

  const bidderMedian = median(bidderCounts);
  const proposalMedian = median(proposalCounts);
  const daysMedian = median(daysToSigning);
  const pctMedian = median(pctIncreaseValues);

  return {
    nCanonicalDeals: canonicalDeals.length,
    medianBidders: bidderMedian === null ? null : { value: bidderMedian, n: bidderCounts.length },
    medianProposals: proposalMedian === null ? null : { value: proposalMedian, n: proposalCounts.length },
    medianDaysToSigning: daysMedian === null ? null : { value: daysMedian, n: daysToSigning.length },
    medianPctIncreaseCash: pctMedian === null ? null : { value: pctMedian, n: pctIncreaseValues.length },
    pctIncreaseCashValues: pctIncreaseValues,
  };
}
